glsl3.frag:
precision highp float;
uniform sampler2D texture;
in vec2 v_uv0;
in vec4 v_light;
#if USE_TINT
  in vec4 v_dark;
#endif
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
uniform block{
  int my_dir;
};
uniform blocktwo{
  float my_proportion;
};
void main () {
  vec4 texColor = vec4(1.0);
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    texColor.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    texColor.a *= texture_tmp.a;
  #else
    texColor *= texture_tmp;
  #endif
  vec4 finalColor;
  #if USE_TINT
    finalColor.a = v_light.a * texColor.a;
    finalColor.rgb = ((texColor.a - 1.0) * v_dark.a + 1.0 - texColor.rgb) * v_dark.rgb + texColor.rgb * v_light.rgb;
  #else
    finalColor = texColor * v_light;
  #endif
  float gray = 0.0;
  if(finalColor.a >= 1.0) {
    if(my_dir == 1) {
        if(v_uv0.y < 1.0 - my_proportion) {
          gray = 0.2126*finalColor.r + 0.7152*finalColor.g + 0.0722*finalColor.b;
        }
    } else if(my_dir == 2) {
        if(v_uv0.y > my_proportion) {
          gray = 0.2126*finalColor.r + 0.7152*finalColor.g + 0.0722*finalColor.b;
        }
    } else if(my_dir == 3) {
        if(v_uv0.x > my_proportion) {
          gray = 0.2126*finalColor.r + 0.7152*finalColor.g + 0.0722*finalColor.b;
        }
    } else {
        if(v_uv0.x < 1.0 - my_proportion) {
          gray = 0.2126*finalColor.r + 0.7152*finalColor.g + 0.0722*finalColor.b;
        }
    }
  }
  ALPHA_TEST(finalColor);
  if(gray > 0.0) {
    gl_FragColor = vec4(gray, gray, gray, finalColor.a);
  } else {
    gl_FragColor = finalColor;
  }
}

